UPDATE lessons SET title='Year 4, Week 30, Lesson 3: Time problems', data=json_patch(data,'{"child_mission":"Time problems combine reading clocks with elapsed time, schedules and simple planning constraints.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same method to a larger number or a new context, then compare two solution paths for accuracy.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nA lesson starts at 11:40 and lasts 50 minutes. When does it end?\n\nFEEDBACK\n12:30.\n\nWATCH FOR\nAdding minutes without rolling 60 minutes into an hour invents times like 11:90.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nSolve twelve time problems (elapsed, end time, fit-in-schedule). Show working for eight.\n\nWrite a short reflection naming one step you corrected and why.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"Time problems combine reading clocks with elapsed time, schedules and simple planning constraints.","lesson_number":3,"lesson_role":"Problem solving","materials":["Paper or typed answer space","Pencil","Optional: place-value chart or number line"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["MA2-NSM-02"],"parent_notes":"Parent: Marking guidance for the independent task: Solve twelve time problems (elapsed, end time, fit-in-schedule). Show working for eight. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new numbers solved with visible working for time; key places/values named. Do not award marks for retyping the model.\n\nParent: Written model 2: Sample misconception: Adding minutes without rolling 60 minutes into an hour invents times like 11:90.. Correction uses 12:30.. Why: restores accurate time.\n\nParent: Likely misconception: Adding minutes without rolling 60 minutes into an hour invents times like 11:90. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Solve one fresh problem that uses time with different numbers from the worked model. Show working and name the places or values that matter.\n\nParent: Short-answer focus 2: Describe one likely mistake with time, show corrected working, and say why the correction works.\n\nParent: Marking notes: Accept any mathematically valid solution that uses new numbers, shows working for time, and names places/values. Reject copied model numbers. / Accept a named misconception about time, corrected working, and a method reason. Reject vague “I was wrong” with no repair..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":1,"explanation":"This matches the taught method for time. The other choices miss a key step or use a common mistake.","options":["A method that skips the key step taught in this lesson","12:30","Adding minutes without rolling 60 minutes into an hour invents times like 11:90","A claim that names no evidence from the lesson material"],"question":"A lesson starts at 11:40 and lasts 50 minutes. When does it end?","type":"multiple_choice"},{"correct_index":0,"explanation":"This is the misconception to avoid for time; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Adding minutes without rolling 60 minutes into an hour invents times like 11:90","Time problems combine reading clocks with elapsed time, schedules and simple planning constraints","12:30","Careful use of problem and explain why it matters with clear evidence"],"question":"Which statement is a common mistake when working with time?","type":"multiple_choice"},{"correct_in